  C('CLAIM-GUARD', 'UI: no static text claims a feature status (“Implemented”, “proven”, “verified”) outside the guard', () => { const vis = html.replace(/<script[\s\S]*?<\/script>/g, ''); expect(!/\b(Implemented|proven|fully verified)\b/.test(vis)); });
  C('CLAIM-GUARD', 'app status table is rendered from the guard (KClaims.Guard), not from literals', () => { const app = fs.readFileSync(path.join(ROOT, 'src/app.js'), 'utf8'); expect(/KClaims\.Guard\(window\.KFEATURES/.test(app) && /applyClaims\(\)/.test(app)); });
  /* feature status shipped with the build is the guarded view of this run */
